mapper.select:
SELECT id, expires_at FROM (
    SELECT o.id, o.screening_id,
        LEAST(o.expires_at, DATE_ADD(o.create_time, INTERVAL 15 MINUTE),
            DATE_SUB(s.sale_end_time, INTERVAL 8 HOUR)) AS expires_at
    FROM orders o JOIN screening s ON s.id = o.screening_id
    WHERE o.status = 0
) due
WHERE expires_at <= #{now}
AND screening_id = #{screeningId}

    AND (expires_at > #{afterExpiry} OR (expires_at = #{afterExpiry} AND id > #{afterId}))

ORDER BY expires_at, id LIMIT #{limit}

mapper.update:
UPDATE orders SET status = 3, version = version + 1, update_time = #{now}
WHERE id = #{orderId} AND status = 0
  AND LEAST(expires_at, DATE_ADD(create_time, INTERVAL 15 MINUTE),
      (SELECT DATE_SUB(s.sale_end_time, INTERVAL 8 HOUR) FROM screening s WHERE s.id = orders.screening_id)) <= #{now}
